type artifactWhere[Q sqlite.Filterable] struct {
	cols        artifactColumns
	ID          sqlite.WhereMod[Q, string]
	CreatedAt   sqlite.WhereMod[Q, time.Time]
	WorkspaceID sqlite.WhereMod[Q, string]
	ItemID      sqlite.WhereMod[Q, string]
	OperationID sqlite.WhereNullMod[Q, string]
	InputKey    sqlite.WhereMod[Q, string]
	Sources     sqlite.WhereMod[Q, types.JSON[[]model.ArtifactSource]]
	ObjectKey   sqlite.WhereMod[Q, string]
	Filename    sqlite.WhereMod[Q, string]
	ContentType sqlite.WhereMod[Q, string]
	Size        sqlite.WhereMod[Q, int64]
	Sha256      sqlite.WhereMod[Q, string]
	Metrics     sqlite.WhereMod[Q, types.JSON[json.RawMessage]]
	ExpiresAt   sqlite.WhereMod[Q, time.Time]
	CreatedBy   sqlite.WhereMod[Q, string]
	R           artifactWhereR[Q]
}

func (artifactWhere[Q]) AliasedAs(alias string) artifactWhere[Q] {
	return buildArtifactWhere[Q](buildArtifactColumns(alias))
}

func buildArtifactWhere[Q sqlite.Filterable](cols artifactColumns) artifactWhere[Q] {
	return artifactWhere[Q]{
		cols:        cols,
		ID:          sqlite.Where[Q, string](cols.ID.Expression),
		CreatedAt:   sqlite.Where[Q, time.Time](cols.CreatedAt.Expression),
		WorkspaceID: sqlite.Where[Q, string](cols.WorkspaceID.Expression),
		ItemID:      sqlite.Where[Q, string](cols.ItemID.Expression),
		OperationID: sqlite.WhereNull[Q, string](cols.OperationID.Expression),
		InputKey:    sqlite.Where[Q, string](cols.InputKey.Expression),
		Sources:     sqlite.Where[Q, types.JSON[[]model.ArtifactSource]](cols.Sources.Expression),
		ObjectKey:   sqlite.Where[Q, string](cols.ObjectKey.Expression),
		Filename:    sqlite.Where[Q, string](cols.Filename.Expression),
		ContentType: sqlite.Where[Q, string](cols.ContentType.Expression),
		Size:        sqlite.Where[Q, int64](cols.Size.Expression),
		Sha256:      sqlite.Where[Q, string](cols.Sha256.Expression),
		Metrics:     sqlite.Where[Q, types.JSON[json.RawMessage]](cols.Metrics.Expression),
		ExpiresAt:   sqlite.Where[Q, time.Time](cols.ExpiresAt.Expression),
		CreatedBy:   sqlite.Where[Q, string](cols.CreatedBy.Expression),
		R:           artifactWhereR[Q]{cols: cols},
	}
}

// artifactWhereR holds the relationship-based filters of
// artifactWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type artifactWhereR[Q sqlite.Filterable] struct {
	cols artifactColumns
}

// HasOperation filters parents that have a matching Operation using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Operations).
func (w artifactWhereR[Q]) HasOperation(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(Operations.NameExpr()),
		sm.Where(Operations.Columns.ID.EQ(w.cols.OperationID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

